def transform(grid):
    h = len(grid)
    w = len(grid[0])
    if h == 0 or w == 0:
        return grid

    # Extract color rows
    colors = []
    seen = set()
    for r in range(h):
        row = grid[r]
        first = row[0]
        if first != 0:
            if all(x == first for x in row):
                if first not in seen:
                    colors.append(first)
                    seen.add(first)
                if len(colors) >= 6:
                    break

    # Take first 6 unique colors
    if len(colors) > 6:
        colors = colors[:6]

    # Split into evens and odds based on color value
    evens = [c for c in colors if c % 2 == 0]
    odds = [c for c in colors if c % 2 == 1]

    # Build output pattern with alternating evens and odds
    output_pattern = []
    i_even = 0
    i_odd = 0

    # 6 iterations to build pattern
    for _ in range(6):
        if i_even < len(evens):
            output_pattern.append(evens[i_even])
            i_even += 1
        if i_odd < len(odds):
            output_pattern.append(odds[i_odd])
            i_odd += 1

    # Extend if needed
    while len(output_pattern) < 6:
        if i_even < len(evens):
            output_pattern.append(evens[i_even])
            i_even += 1

    # Fill output grid with pattern cycling
    output = []
    for i in range(h):
        c = output_pattern[i % len(output_pattern)] if len(output_pattern) > 0 else 0
        output.append([c] * w)

    return output
